                { interval: "90,000 km", timeLimit: "5 years", task: "Timing Belt & Water Pump", details: "Absolutely critical. Replace the timing belt, tensioner, idler rollers, and water pump. The 40V engine is highly interference.", parts: ["Timing Belt Kit", "Water Pump"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "700 - 1100 EUR" }, 
                { interval: "100,000 km", timeLimit: "N/A", task: "Valve Cover & Tensioner Gaskets", details: "Replace the rubber gaskets and the half-moon seals under the chain tensioners to stop persistent oil leaks.", parts: ["VCG Set", "CCT Gaskets"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 - 400 EUR" }, 
                { interval: "80,000 km", timeLimit: "N/A", task: "PCV Suction Pump Replacement", details: "Replace the plastic suction jet pump to cure massive vacuum leaks and hard brake pedals.", parts: ["Suction Jet Pump"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 EUR" }, 
                { interval: "100,000 km", timeLimit: "N/A", task: "Vacuum Line Overhaul", details: "Replace all brittle cloth-braided vacuum hoses with silicone to fix hesitation and ensure intake flaps actuate.", parts: ["Silicone Hose Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "30 - 50 EUR" }, 
                { interval: "80,000 km", timeLimit: "N/A", task: "Ignition Coil Replacement", details: "Proactively replace the individual coil packs to prevent severe engine misfires under load.", parts: ["8x Ignition Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "200 - 300 EUR" } 
