                { interval: "10,000 km", timeLimit: "1 year", task: "Engine Oil & Filter Change", details: "Use quality 5W-40 synthetic. Clean oil is the ONLY way to delay the inevitable camshaft wear.", parts: ["Oil Filter", "5.4L 5W-40 Oil"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "70 - 110 EUR" }, 
                { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter Replacement", details: "A clogged filter destroys the fragile MAF sensor.", parts: ["Air Filter Element"], importance: "High", laborDifficulty: "Easy", estimatedCost: "20 - 35 EUR" }, 
                { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Air Filter Replacement", details: "Replace filter to keep HVAC blower motor clear of debris.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "15 - 30 EUR" }, 
                { interval: "30,000 km", timeLimit: "2 years", task: "Fuel Filter Replacement", details: "CRITICAL: The VP44 uses fuel for internal lubrication. A clogged filter starves and destroys the pump. Pre-fill the new filter!", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "40 - 70 EUR" } 
