                { interval: "80,000 km", timeLimit: "N/A", task: "Rear Differential Fluid", details: "Change hypoid gear oil on Quattro models.", parts: ["75W-90 GL-5"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "50 - 80 EUR" }, 
                { interval: "100,000 km", timeLimit: "5 years", task: "Power Steering Fluid Flush", details: "Flush the green CHF 11S fluid to protect the 30-year-old steering rack seals from blowing out.", parts: ["1.0L CHF 11S"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 - 70 EUR" } 
