                { interval: "100,000 km", timeLimit: "N/A", task: "Vacuum Line Overhaul", details: "Replace all brittle cloth-braided vacuum hoses with silicone to fix hesitation and ensure intake flaps actuate.", parts: ["Silicone Hose Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "30 - 50 EUR" }, 
                { interval: "120,000 km", timeLimit: "N/A", task: "Ignition Cables & Coil Packs", details: "Replace the high-tension spark plug wires and inspect the twin coil packs for hairline cracks.", parts: ["Ignition Wire Set", "2x Coil Packs"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "250 - 400 EUR" }, 
                { interval: "80,000 km", timeLimit: "N/A", task: "PCV Valve Cleaning/Replacement", details: "Ensure the crankcase ventilation system is clear to prevent blown oil seals.", parts: ["PCV Valve"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" } 
