                { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter Replacement", details: "Ensure maximum airflow to the 40-valve cylinder heads.", parts: ["Air Filter Element"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 - 40 EUR" }, 
                { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Air Filter Replacement", details: "Replace filter to keep HVAC blower motor clear of debris.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "15 - 30 EUR" }, 
                { interval: "60,000 km", timeLimit: "4 years", task: "Fuel Filter Replacement", details: "Located under the car. Prevents the archaic fuel pump from overworking and burning out its relay.", parts: ["Fuel Filter"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "30 - 60 EUR" } 
