                { interval: "60,000 km", timeLimit: "4 years", task: "Automatic Transmission Fluid", details: "Drain the pan, replace the filter, and refill with Lifeguard 5 to save the fragile 5HP ZF.", parts: ["9.5L ATF", "Filter & Gasket"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "200 - 350 EUR" }, 
                { interval: "80,000 km", timeLimit: "N/A", task: "Front Differential Fluid", details: "Drain and fill gear oil to prevent bearing whine.", parts: ["75W-90 GL-4"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "50 - 80 EUR" }, 
                { interval: "80,000 km", timeLimit: "N/A", task: "Rear Differential Fluid", details: "Change hypoid gear oil on Quattro models.", parts: ["75W-90 GL-5"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "50 - 80 EUR" }, 
                { interval: "100,000 km", timeLimit: "5 years", task: "Power Steering Fluid Flush", details: "Flush the green CHF 11S fluid to protect the 30-year-old steering rack seals from blowing out.", parts: ["1.0L CHF 11S"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 - 70 EUR" } 
