            { interval: "100,000 km", timeLimit: "N/A", task: "DPF Ash Mass Check", details: "Check the DPF ash volume using VCDS diagnostic software. If full, it must be cleaned.", parts: ["Diagnostic"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, 
            { interval: "100,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "Inspect and replace the main drive belt and tensioner pulley.", parts: ["Belt Kit", "Tensioner"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 150 EUR" } 
