        { partName: "Piezo Fuel Injector", category: "Fuel", oem: { brand: "Audi Genuine", code: "059130277BD", approxPrice: "550 EUR" }, crossRef: { brand: "Bosch", code: "0445115078", approxPrice: "280 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059130277bd", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059130277bd" }, note: "Requires 8 units. Must use 'BD' revision to prevent dripping and melting pistons." },
        { partName: "Mass Air Flow Sensor", category: "Engine Management", oem: { brand: "Audi Genuine", code: "057906461C", approxPrice: "220 EUR" }, crossRef: { brand: "Bosch", code: "0281002430", approxPrice: "110 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/057906461c", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=057906461c" }, note: "Requires 2 units. Failing MAF causes severe hesitation." },
        { partName: "DPF Pressure Sensor", category: "Emissions", oem: { brand: "Audi Genuine", code: "059906051A", approxPrice: "70 EUR" }, crossRef: { brand: "Bosch", code: "0281002710", approxPrice: "35 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059906051a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059906051a" }, note: "Crucial for correct DPF regeneration cycles." },
        { partName: "EGR Cooler", category: "Emissions", oem: { brand: "Audi Genuine", code: "057131511A", approxPrice: "450 EUR" }, crossRef: { brand: "Pierburg", code: "7.09720.00.0", approxPrice: "280 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/057131511a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=057131511a" }, note: "Prone to leaking coolant internally directly into the exhaust." },
        { partName: "Injector Copper Seals", category: "Engine", oem: { brand: "Audi Genuine", code: "059130519", approxPrice: "5 EUR" }, crossRef: { brand: "Bosch", code: "F00VC17503", approxPrice: "2 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059130519", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059130519" }, note: "Requires 8. Replace to prevent 'black death' blow-by." },
        { partName: "Glow Plugs", category: "Ignition", oem: { brand: "Audi Genuine", code: "059906163J", approxPrice: "25 EUR" }, crossRef: { brand: "Beru", code: "GE115", approxPrice: "12 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059906163j", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059906163j" }, note: "Requires 8 units. Use ceramic paste during installation to prevent threads seizing." },
        { partName: "Engine Oil Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "057115561K", approxPrice: "22 EUR" }, crossRef: { brand: "Mann-Filter", code: "HU842x", approxPrice: "12 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/057115561k", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=057115561k" }, note: "High capacity fleece element." },
        { partName: "Fuel Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "8T0127401A", approxPrice: "55 EUR" }, crossRef: { brand: "Mann-Filter", code: "PU8008/1", approxPrice: "25 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/8t0127401a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=8t0127401a" }, note: "Replace every 30k km to protect the CP3 pumps." },
        { partName: "ZF Transmission Filter", category: "Drivetrain", oem: { brand: "Audi Genuine", code: "09L398009A", approxPrice: "250 EUR" }, crossRef: { brand: "ZF", code: "1068298062", approxPrice: "120 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/09l398009a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=09l398009a" }, note: "Includes integrated filter for the ZF 6-speed transmission." }
