            { interval: "100,000 km", timeLimit: "N/A", task: "MAF Sensor Replacement", details: "Replace both MAF sensors if acceleration feels sluggish or uneven.", parts: ["2x Bosch MAF"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "200 - 300 EUR" }, 
            { interval: "100,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "Inspect and replace the main drive belt and tensioner pulley.", parts: ["Belt Kit", "Tensioner"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 - 250 EUR" } 
