            { interval: "100,000 km", timeLimit: "N/A", task: "Air Suspension Strut Inspection", details: "Inspect the rubber air springs for dry rotting and leaks. A leaking strut will cause the compressor to burn out.", parts: ["Diagnostic"], importance: "High", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, 
            { interval: "100,000 km", timeLimit: "N/A", task: "Control Arm Bushings", details: "The colossal weight of the W12 destroys front control arm bushings rapidly.", parts: ["Control Arm Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "500 - 800 EUR" }, 
            { interval: "100,000 km", timeLimit: "N/A", task: "Four-Wheel Alignment", details: "Perform a full alignment to protect tire wear.", parts: ["None"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "80 - 120 EUR" } 
