        { partName: "Fuel Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "8T0127401A", approxPrice: "55 EUR" }, crossRef: { brand: "Mann-Filter", code: "PU8008/1", approxPrice: "25 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/8t0127401a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=8t0127401a" }, note: "Replace every 30k km to protect the HPFP." },
        { partName: "ZF Transmission Filter & Pan", category: "Drivetrain", oem: { brand: "Audi Genuine", code: "0D5398009A", approxPrice: "250 EUR" }, crossRef: { brand: "ZF", code: "1087298365", approxPrice: "120 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/0d5398009a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=0d5398009a" }, note: "Includes integrated filter for the ZF 8-speed transmission." }
