            { interval: "80,000 km", timeLimit: "N/A", task: "Rear Differential Fluid", details: "Change hypoid gear oil on Quattro models.", parts: ["75W-90 GL-5"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "50 - 80 EUR" }, 
            { interval: "80,000 km", timeLimit: "N/A", task: "Transfer Case Fluid", details: "Change the specialized fluid in the Torsen center differential.", parts: ["75W-90 GL-4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 150 EUR" } 
