            { interval: "80,000 km", timeLimit: "N/A", task: "Ignition Coil Replacement", details: "Proactively replace the ignition coils. Engine heat breaks down their internal insulation, leading to sudden failure.", parts: ["6x Eldor Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "150 - 250 EUR" }, 
            { interval: "100,000 km", timeLimit: "5 years", task: "PCV, Thermostat & Water Pump", details: "Proactively replace the PCV module and the thermal management system before they crack and cause severe leaks.", parts: ["PCV Assy", "Thermostat", "Water Pump"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "600 - 900 EUR" }, 
            { interval: "100,000 km", timeLimit: "N/A", task: "Intake Valve Walnut Blasting", details: "Physically blast the carbon deposits off the intake valves using crushed walnut shells. Restores massive amounts of lost power.", parts: ["Intake Gaskets", "Blasting Media"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 - 500 EUR" }, 
            { interval: "100,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "Inspect and replace the main accessory drive belt. Highly critical as it drives the 48V BAS unit.", parts: ["Belt Kit", "Tensioner"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 150 EUR" }, 
            { interval: "100,000 km", timeLimit: "N/A", task: "GPF Sensor Check", details: "Monitor the Gasoline Particulate Filter differential pressure sensors to avoid limp mode.", parts: ["Diagnostic"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "0 EUR" } 
